From 5fb7114f814645ebf679a8228350e9770bf3f009 Mon Sep 17 00:00:00 2001
From: Ken Sharp <Ken.Sharp@artifex.com>
Date: Wed, 10 Apr 2024 16:44:26 +0100
Subject: [PATCH] graphics library - clean up tile clipper device on
 initialisation error

OSS-fuzz bug #67932

This turns out to be another case like Bug #705722 and I've opted to fix
it in exactly the same way. I've also scanned the other cases where
tile_fill_init() is used, and fixed those too.

Quoting the text from commit a003e870a11d13659666311e8b3059ba9fda3651

-----------------------------------------------------------------------
If initialisation for tile filling fails, make sure to cleanup the tile
clipper device if it was setup. The reason being that clipper device forwards
drawing operations to a memory device, embedded in itself (i.e. not a separate
memory allocation just for the memory device).

This means if the clipper device (with its target set to that internal memory
device) persists until a gc run occurs, when the garbager attempts to reloc the
clipper's target pointer, it will access adjacent values in device structure,
not the memory manager header it expects. Thus it will reloc to a nonsensical
location, and ultimately, will crash.
---
 base/gxp1fill.c | 23 ++++++++++++++++++-----
 1 file changed, 18 insertions(+), 5 deletions(-)

diff --git a/base/gxp1fill.c b/base/gxp1fill.c
index 6b5b43b..4941064 100644
--- a/base/gxp1fill.c
+++ b/base/gxp1fill.c
@@ -1,4 +1,4 @@
-/* Copyright (C) 2001-2023 Artifex Software, Inc.
+/* Copyright (C) 2001-2024 Artifex Software, Inc.
    All Rights Reserved.

    This software is provided AS-IS with no warranty, either express or
@@ -518,7 +518,7 @@ gx_dc_pure_masked_fill_rect(const gx_device_color * pdevc,
      */
     code = tile_fill_init(&state, pdevc, dev, true);
     if (code < 0)
-        return code;
+        goto exit;
     if (state.pcdev == dev || ptile->is_simple)
         code = (*gx_dc_type_data_pure.fill_rectangle)
             (pdevc, x, y, w, h, state.pcdev, lop, source);
@@ -529,6 +529,7 @@ gx_dc_pure_masked_fill_rect(const gx_device_color * pdevc,
         code = tile_by_steps(&state, x, y, w, h, ptile, &ptile->tmask,
                              tile_masked_fill);
     }
+exit:
     if (CLIPDEV_INSTALLED) {
         tile_clip_free((gx_device_tile_clip *)state.cdev);
         state.cdev = NULL;
@@ -552,7 +553,7 @@ gx_dc_devn_masked_fill_rect(const gx_device_color * pdevc,
      */
     code = tile_fill_init(&state, pdevc, dev, true);
     if (code < 0)
-        return code;
+        goto exit;
     if (state.pcdev == dev || ptile->is_simple) {
         gx_device_color dcolor = *pdevc;

@@ -574,6 +575,7 @@ gx_dc_devn_masked_fill_rect(const gx_device_color * pdevc,
         code = tile_by_steps(&state, x, y, w, h, ptile, &ptile->tmask,
                              tile_masked_fill);
     }
+exit:
     if (CLIPDEV_INSTALLED) {
         tile_clip_free((gx_device_tile_clip *)state.cdev);
         state.cdev = NULL;
@@ -593,7 +595,7 @@ gx_dc_binary_masked_fill_rect(const gx_device_color * pdevc,

     code = tile_fill_init(&state, pdevc, dev, true);
     if (code < 0)
-        return code;
+        goto exit;
     if (state.pcdev == dev || ptile->is_simple)
         code = (*gx_dc_type_data_ht_binary.fill_rectangle)
             (pdevc, x, y, w, h, state.pcdev, lop, source);
@@ -604,6 +606,7 @@ gx_dc_binary_masked_fill_rect(const gx_device_color * pdevc,
         code = tile_by_steps(&state, x, y, w, h, ptile, &ptile->tmask,
                              tile_masked_fill);
     }
+exit:
     if (CLIPDEV_INSTALLED) {
         tile_clip_free((gx_device_tile_clip *)state.cdev);
         state.cdev = NULL;
@@ -623,7 +626,7 @@ gx_dc_colored_masked_fill_rect(const gx_device_color * pdevc,

     code = tile_fill_init(&state, pdevc, dev, true);
     if (code < 0)
-        return code;
+        goto exit;
     if (state.pcdev == dev || ptile->is_simple)
         code = (*gx_dc_type_data_ht_colored.fill_rectangle)
             (pdevc, x, y, w, h, state.pcdev, lop, source);
@@ -634,6 +637,7 @@ gx_dc_colored_masked_fill_rect(const gx_device_color * pdevc,
         code = tile_by_steps(&state, x, y, w, h, ptile, &ptile->tmask,
                              tile_masked_fill);
     }
+exit:
     if (CLIPDEV_INSTALLED) {
         tile_clip_free((gx_device_tile_clip *)state.cdev);
         state.cdev = NULL;
@@ -1397,6 +1401,15 @@ gx_trans_pattern_fill_rect(int xmin, int ymin, int xmax, int ymax,
             gx_strip_bitmap tbits;

             code = tile_fill_init(&state_clist_trans, pdevc, dev, false);
+            if (code < 0)
+            {
+                /* Can't use CLIPDEV_INSTALLED macro because it assumes a tile_fill_state_t structure, called 'state' */
+                if (state_clist_trans.cdev != NULL) {
+                    tile_clip_free((gx_device_tile_clip *)state_clist_trans.cdev);
+                    state_clist_trans.cdev = NULL;
+                }
+                return code;
+            }

             state_clist_trans.phase.x = phase.x;
             state_clist_trans.phase.y = phase.y;
